records["Locales/enUS.lua"]={bytes=261760,hash=3984991999,oldBytes=260311,oldHash=227334449,changes={{at=907,current="L['/rm perf engine [lean|standard] - Show or choose the rotation evaluation engine.'] = '/rm perf engine [lean||standard] - Show or choose the rotation evaluation engine.'\nL['Usage: /rm perf engine [lean|standard]'] = 'Usage: /rm perf engine [lean||standard]'\nL['Evaluation engine: %s'] = true\n",previous=""},{at=19860,current="L[\"Idle Re-check Interval (seconds)\"] = true\nL[\"Auto-Switch Re-check Interval (seconds)\"] = true\n",previous=""},{at=50420,current="L[\"Drag to resize the list. Double-click to reset.\"] = true\n",previous=""},{at=125373,current="L[\"Help.General.idle_poll\"] = \"Out of combat with no target and no focus, Rotation Master skips a polling tick unless something it watches has changed: auras, cooldowns, health or power of you, your pet or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at least this often, for time-based conditions (aura or cooldown remaining), distance, and custom code. In combat, with any target or focus, or while configuration is open, every polling tick is evaluated. Zero evaluates every polling tick.\"\nL[\"Help.General.autoswitch_poll\"] = \"With automatic switching, Rotation Master checks this often, in and out of combat, whether a different rotation's switch conditions now match, so conditions that change on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and pet changes are checked straight away. Zero turns automatic switching off. Choosing a rotation manually still overrides automatic switching until you choose Auto again.\"\n",previous=""}}}
