records["UI/rotation_browser.lua"]={bytes=25973,hash=1966800273,oldBytes=25536,oldHash=2453721151,changes={{at=808,current="    local frame=addon:TrackWorkbenchSize(CreateFrame(\"Frame\",nil,parent));frame:SetPoint(\"TOPLEFT\",parent,\"TOPLEFT\",0,0)\n",previous="    local frame=CreateFrame(\"Frame\",nil,parent);frame:SetPoint(\"TOPLEFT\",parent,\"TOPLEFT\",0,0)\n"},{at=1044,current="    local specs=addon:TrackWorkbenchSize(CreateFrame(\"Frame\",nil,frame));browser.specs=specs\n    local left=addon:TrackWorkbenchSize(CreateFrame(\"Frame\",nil,frame));browser.left=left\n    local detail=addon:TrackWorkbenchSize(CreateFrame(\"Frame\",nil,frame));browser.detail=detail\n",previous="    local specs=CreateFrame(\"Frame\",nil,frame);browser.specs=specs\n    local left=CreateFrame(\"Frame\",nil,frame);browser.left=left\n    local detail=CreateFrame(\"Frame\",nil,frame);browser.detail=detail\n"},{at=4149,current="    -- Rows follow the list column; the scroll bar reserves space only when shown.\n    function list:OnWorkbenchColumnResized(width) empty:SetWidth(math.max(40,width-8));browser:RefreshViewport() end\n    browser.splitter=addon:CreateWorkbenchSplitter(frame,function() if browser.active then browser:Layout() end end)\n",previous=""},{at=21850,current="        self.splitter:Place(geometry)\n        addon:LayoutWorkbenchRow({self.filters.all,self.filters.builtin,self.filters.custom},0,28,leftWidth)\n",previous="        for index,key in ipairs({'all','builtin','custom'}) do local filter=self.filters[key];filter:ClearAllPoints();filter:SetPoint('TOPLEFT',left,'TOPLEFT',(index-1)*(leftWidth+4)/3,-28);filter:SetWidth((leftWidth-8)/3) end\n"},{at=22221,current="        list:SetPoint(\"TOPLEFT\",left,\"TOPLEFT\",0,-listTop);list:SetHeight(math.max(64,left:GetHeight()-listTop-36-footerHeight))\n        list:SetWorkbenchColumnWidth(leftWidth);child:SetWidth(list:GetWidth())\n        count:ClearAllPoints();count:SetPoint(\"BOTTOMLEFT\",left,\"BOTTOMLEFT\",0,footerHeight+8);count:SetWidth(leftWidth)\n",previous="        list:SetPoint(\"TOPLEFT\",left,\"TOPLEFT\",0,-listTop);list:SetSize(leftWidth-24,math.max(64,left:GetHeight()-listTop-36-footerHeight))\n        child:SetWidth(list:GetWidth())\n        count:ClearAllPoints();count:SetPoint(\"BOTTOMLEFT\",left,\"BOTTOMLEFT\",0,footerHeight+8)\n"},{at=22593,current="        for _,control in ipairs({new,duplicate,import,compare}) do control:ClearAllPoints();control:SetWidth(buttonWidth);addon:AlignWorkbenchTextLeft(control,24) end\n",previous="        for _,control in ipairs({new,duplicate,import,compare}) do control:ClearAllPoints();control:SetWidth(buttonWidth) end\n"}}}
records["UI/rotation_canvas.lua"]={bytes=30131,hash=2618430725,oldBytes=27894,oldHash=3639761049,changes={{at=468,current="-- The scene builder lays cards out at their 340 px design width. A diagram\n-- keeps that (it pans and zooms in two dimensions), but the vertical list and\n-- the cooldown grid fill the viewport: list cards reach the right edge less\n-- 8 px per nested branch, and grid columns share the row. Nothing narrows.\nlocal listIndent,gridGap,gridCardMaximum=24,24,600\nfunction addon:FitRotationSceneWidth(scene,viewport)\n    if type(scene)~='table' or not finite(viewport) then return scene end\n    local right=math.max(0,viewport-4);local widest=0\n    local function stretch(item,inset,base)\n        local depth=math.max(0,math.floor((item.x-base)/listIndent+.5))\n        item.width=math.max(item.width,right-depth*8-inset-item.x)\n    end\n    if scene.layout=='list' then\n        for _,card in ipairs(scene.cards) do stretch(card,0,0) end\n        for _,group in ipairs(scene.groups or {}) do if group.kind=='arm' then stretch(group,4,20) else stretch(group,0,0) end end\n        for _,target in ipairs(scene.dropTargets or {}) do stretch(target,0,0) end\n    elseif scene.layout=='grid' and #(scene.groups or {})==0 then\n        local design=340;local pitch=design+gridGap;local columns=0\n        for _,card in ipairs(scene.cards) do columns=math.max(columns,math.floor(card.x/pitch+.5)+1) end\n        if columns==0 then return scene end\n        local each=math.max(design,math.min(gridCardMaximum,(right-(columns-1)*gridGap)/columns))\n        local function place(item) local column=math.floor(item.x/pitch+.5);item.x=column*(each+gridGap);item.width=each end\n        for _,card in ipairs(scene.cards) do if card.width==design then place(card) end end\n        for _,target in ipairs(scene.dropTargets or {}) do\n            if target.width==design then place(target) elseif target.width>design then target.x=0;target.width=columns*each+(columns-1)*gridGap end\n        end\n    else return scene end\n    for _,card in ipairs(scene.cards) do widest=math.max(widest,card.x+card.width) end\n    for _,group in ipairs(scene.groups or {}) do widest=math.max(widest,group.x+group.width) end\n    scene.width=math.max(scene.width or 0,widest)\n    return scene\nend\n",previous=""},{at=2902,current="    canvas.cameraHost=self:TrackWorkbenchSize(CreateFrame('Frame',nil,canvas.surface))\n    canvas.child=self:TrackWorkbenchSize(CreateFrame('Frame',nil,canvas.cameraHost));canvas.child:SetPoint('TOPLEFT')\n    canvas.horizontal=addon:CreateWorkbenchScrollBar(parent,'HORIZONTAL');addon:TrackWorkbenchSize(canvas.horizontal)\n",previous="    canvas.cameraHost=CreateFrame('Frame',nil,canvas.surface)\n    canvas.child=CreateFrame('Frame',nil,canvas.cameraHost);canvas.child:SetPoint('TOPLEFT')\n    canvas.horizontal=addon:CreateWorkbenchScrollBar(parent,'HORIZONTAL')\n"}}}
